import numpy as np

def check_line_segments():
    """Check if 5s form line segments between specific point pairs"""

    # For Demo 1, check if 5s lie on line segments between any two non-zero points

    demo1_points = {
        '1_orig': (4, 3),
        '1_copy': (3, 5), 
        '2_orig': (7, 5),
        '2_copy': (7, 1)
    }

    demo1_fives = [(4,4), (4,5), (7,2), (7,3), (7,4)]

    def on_line_segment(p1, p2, p):
        """Check if point p lies on segment from p1 to p2 (inclusive)"""
        r1, c1 = p1
        r2, c2 = p2
        r, c = p

        # Check if col matches one endpoint and row is between
        if c == c1 or c == c2:
            return min(r1, r2) <= r <= max(r1, r2)
        # Check if row matches one endpoint and col is between
        if r == r1 or r == r2:
            return min(c1, c2) <= c <= max(c1, c2)

        return False

    print("Demo 1: Checking which segment each 5 belongs to:")
    for fiv_pos in demo1_fives:
        found = None
        for name1, p1 in list(demo1_points.items()):
            for name2, p2 in demo1_points.items():
                if name1 < name2:  # Avoid duplicates
                    if on_line_segment(p1, p2, fiv_pos):
                        found = f"({name1},{name2})"
                        break
            if found:
                break
        print(f"  5 at {fiv_pos}: belongs to {found}")

    # Try all 4 points including diagonals
    points_list = list(demo1_points.values())
    print("\nAll possible segments:")
    for i, p1 in enumerate(points_list):
        for j, p2 in enumerate(points_list):
            if i < j:
                on_seg_5 = [fiv for fiv in demo1_fives if on_line_segment(p1, p2, fiv)]
                if on_seg_5:
                    print(f"  Segment {p1}-{p2} contains: {on_seg_5}")

