import numpy as np

def find_bridge_pattern():
    """Figure out exactly which cells become 5s"""

    def get_all_points(demo):
        """Get all non-zero positions including originals and copies"""
        pts = []
        if demo == "demo1":
            # Originals
            pts.append(((4, 3), 1, 'orig'))
            pts.append(((7, 5), 2, 'orig'))
            # Copies
            pts.append(((3, 5), 1, 'copy'))
            pts.append(((7, 1), 2, 'copy'))
        elif demo == "demo2":
            pts.append(((2, 3), 3, 'orig'))
            pts.append(((5, 6), 1, 'orig'))
            pts.append(((5, 3), 3, 'copy'))
            pts.append(((4, 8), 1, 'copy'))

        return pts

    demo1_fives = {(4,4), (4,5), (7,2), (7,3), (7,4)}
    demo2_fives = {(3,3), (4,3), (5,7), (5,8)}

    for demo, expected_fives in [("demo1", demo1_fives), ("demo2", demo2_fives)]:
        print(f"\n=== {demo.upper()} ===")
        pts = get_all_points(demo)

        # Check ALL pairs for horizontal AND vertical segments
        # A segment fills all intermediate cells (exclusive of endpoints)

        filled_pairs = []

        for i, (p1, v1, type1) in enumerate(pts):
            for j, (p2, v2, type2) in enumerate(pts):
                if i < j:
                    r1, c1 = p1
                    r2, c2 = p2

                    # Check if same row (horizontal segment)
                    if r1 == r2:
                        # Fill all cells between (exclusive)
                        min_c = min(c1, c2) + 1
                        max_c = max(c1, c2)
                        seg_cells = {(r1, c) for c in range(min_c, max_c)}

                        pair_match = set(seg_cells) & expected_fives
                        if pair_match:
                            filled_pairs.append((type1, type2, seg_cells, pair_match))

                    # Check if same column (vertical segment)  
                    elif c1 == c2:
                        min_r = min(r1, r2) + 1
                        max_r = max(r1, r2)
                        seg_cells = {(r, c1) for r in range(min_r, max_r)}

                        pair_match = set(seg_cells) & expected_fives
                        if pair_match:
                            filled_pairs.append((type1, type2, seg_cells, pair_match))

        print(f"Pairs that produce 5-fills: {filled_pairs}")

        # Now show which cells are filled by how many pairs
        print("\nCoverage analysis:")
        coverage = {}
        for type1, type2, seg, match in filled_pairs:
            for cell in seg:
                coverage[cell] = coverage.get(cell, 0) + 1

        for cell, count in sorted(coverage.items()):
            mark = "✓" if cell in expected_fives else "✗"
            print(f"  {cell}: covered by {count} pair(s) {mark}")

